function answerFrame(ws: WebSocket, session: ChatSession, validation: ValidationResult, sessionStore: SessionStore, history?: {enabled: boolean}): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') void handleListSessions(ws, session, message, sessionStore, history);
}

async function handleListSessions(ws: WebSocket, session: ChatSession, message: ListSessionsMessage, sessionStore: SessionStore, history?: {enabled: boolean}): Promise<void> {
  if (!history?.enabled || !sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled');
    return;
  }
  try {
    const sessions = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    sendJson(ws, {type: 'session_list', sessions: sessions.map(s => ({...s, createdAt: (s.createdAt instanceof Date ? s.createdAt : new Date(s.createdAt)).toISOString(), updatedAt: (s.updatedAt instanceof Date ? s.updatedAt : new Date(s.updatedAt)).toISOString()}))});
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled');
      return;
    }
    throw error;
  }
}

