it('answers UNSUPPORTED when the store has no listFor, history is disabled, or store throws StoreCannotList, and SERVER_ERROR with a ws error log when listFor throws', async () => {
  const inner = new InMemorySessionStore();
  const withoutList = await startEngine(delegatingTo(inner), 'u1', {enabled: true});
  const historyDisabled = await startEngine({
    ...delegatingTo(inner),
    listFor: () => Promise.resolve([]),
  }, 'u1', undefined);
  const storeCannotList = await startEngine({
    ...delegatingTo(inner),
    listFor: () => Promise.reject(new StoreCannotList('cannot list')),
  }, 'u1', {enabled: true});
  const failingList = await startEngine({
    ...delegatingTo(inner),
    listFor: () => Promise.reject(new Error('database offline')),
  }, 'u1', {enabled: true});

  const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
  const disabled = await askAfterConnect(historyDisabled, {type: 'list_sessions'});
  const cannotList = await askAfterConnect(storeCannotList, {type: 'list_sessions'});
  const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

  expect({
    unimplemented: unimplemented.frames.map(frame => ({type: frame.type, code: frame.code})),
    disabled: disabled.frames.map(frame => ({type: frame.type, code: frame.code})),
    cannotList: cannotList.frames.map(frame => ({type: frame.type, code: frame.code})),
    failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
    logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
  }).toEqual({
    unimplemented: [{type: 'error', code: 'UNSUPPORTED'}],
    disabled: [{type: 'error', code: 'UNSUPPORTED'}],
    cannotList: [{type: 'error', code: 'UNSUPPORTED'}],
    failed: [{type: 'error', code: 'SERVER_ERROR'}],
    logged: [
      {
        level: 'error',
        category: 'ws',
        message: expect.any(String),
        fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
      },
    ],
  });
});

